    s.wo = 'approved';
    s.workOrder = { ...ENGINE.workOrder(s, k, cfg, { by: 'operator (demo)' }), delivery: API ? 'sending' : 'local' };
    const w = s.workOrder;
    // n8n gets what the manager saw, so the stored record stands on its own. The success message waits for n8n's answer (see act).
    act(s, 'approve_work_order', { stop: k, workOrderId: w.id, priority: w.priority, dueBy: w.dueBy, tier: w.tier, hazard: w.hazard, why: w.why, checks: w.checks, mapUrl: w.mapUrl });
    toast(API ? `Sending the ${w.priority} inspection for ${s.id} to n8n…` : `Local demo: ${w.priority} inspection for ${s.id} saved in this browser only · due ${fmtDate(w.dueBy)}`);
  } else {
    if (s.wo === 'rejected') return;
    s.wo = 'rejected';
    if (s.workOrder) s.workOrder = { ...s.workOrder, status: 'cancelled' };
    act(s, 'reject_work_order', { stop: k, workOrderId: s.workOrder ? s.workOrder.id : null });
