    localStorage.setItem('tc-state', JSON.stringify({ decisions, audit: audit.slice(0, 200) }));
  } catch (e) {}
}
function loadSaved() {
  if (API) {
    for (const w of D.workOrders || []) {
      const s = byId(w.segment); if (!s) continue;
      if (w.status === 'rejected') s.wo = 'rejected';
      else { s.wo = w.status === 'cancelled' ? 'rejected' : 'approved'; s.workOrder = { ...w, delivery: 'n8n' }; }
    }
    // The n8n feed sends each segment's work order as a thin row {id, status, priority, tier}. The pages read
    // checks, dueBy, why and the map link too, so fill those in from the engine and keep n8n's work order id.
    for (const s of D.segments) {
      const w = s.workOrder; if (!w) continue;
      const st = String(w.status || '');
      if (st === 'pending_approval') { delete s.workOrder; continue; }   // drafted, not approved yet: still shows Approve
      if (st === 'rejected' || st === 'cancelled') { s.wo = 'rejected'; delete s.workOrder; continue; }
      const given = { id: w.id };   // n8n's priority is normal/high; the page keeps its own P1-P3 labels
      s.workOrder = { ...ENGINE.workOrder(s, 'y10', cfg, {}), ...given, status: 'open', delivery: 'n8n' };
      s.wo = 'approved';
    }
    for (const s of D.segments) if (s.override && !s.override.stop) s.override.stop = 'y10';
