  const hw = (cfg.horizons || {})[stop] || [];
  const when = stop === 'y0' ? 'observed 1995–2025' : `${hw[0] || 2026}–${hw[1] || ''} vs 1995–2025`;
  if (!ovLedger.children.length) {
    ovLedger.innerHTML = ['risk', 'rain', 'freezeThaw', 'fire', 'drought', 'crossing'].map((k) =>
      `<a class="cell" href="#/triage" data-k="${k}" title="${esc(HELP[k])}"><div class="e"></div><div class="v"></div><div class="s"></div>${k === 'risk' ? '<div class="stack"></div>' : ''}</a>`).join('');
  }
