// The tool has two halves: protect the pipeline (risk) and put stable right-of-way to work (build).
// The money case adds them up, then says plainly whether to run it and what that depends on.
function moneyCase(c = cfg) {
  const sum = summarize(c), yrs = years(), share = c.money.partnerShare;
  const operatorLease = Math.round(sum.leaseRevenueYr * (1 - share) * yrs);
  return { sum, yrs, operatorLease, partnerLease: Math.round(sum.partnerRevenueYr * yrs), risk: sum.netValue, total: sum.netValue + operatorLease };
}
function renderMoney() {
  const m = moneyCase(), s = m.sum, yrs = m.yrs, share = cfg.money.partnerShare, rate = cfg.money.leaseRatePerAcreYr;
  mDek.textContent = `Over ${yrs} years, ${stop === 'y0' ? 'if the climate stayed at its 1995–2025 baseline' : 'under the ' + STOP_LABEL[stop] + ' climate projection'}. Scenario maths on editable assumptions, not measured savings. The pipeline-protection case is judged on its own; solar leasing is shown separately as a conditional opportunity. Move any assumption and the result updates.`;
  mStops.innerHTML = stopSeg();

  // Lease rate at which the combined case breaks even (operator share only).
  const acres = rate ? s.leaseRevenueYr / rate : 0, opShare = 1 - share;
  const beRate = acres && opShare > 0 ? Math.ceil(Math.max(0, -m.risk) / (acres * opShare * yrs)) : null;
  const extras = `Landowner partners also get <b>${fmt$(m.partnerLease)}</b>, and the panels avoid <b>${(s.avoidedTco2Yr || 0).toLocaleString()} tCO₂</b> a year. Neither is counted in the total.`;
  // What this run measurably did: a ranked shortlist. Shares are of the 0-100 priority index, not of failure probability.
  const scored = segs.filter((x) => x.risk[stop].score != null).sort((p, q) => q.risk[stop].score - p.risk[stop].score);
  const flagged = scored.filter((x) => x.risk[stop].score >= cfg.tiers.amber);
  const short = flagged.length ? flagged : scored.slice(0, Math.min(3, scored.length));
  const sumAll = scored.reduce((t, x) => t + x.risk[stop].score, 0), sumShort = short.reduce((t, x) => t + x.risk[stop].score, 0);
  const VISIT_H = cfg.money.visitHours || 6;
  const kmAll = scored.reduce((t, x) => t + x.lengthM / 1000, 0), kmShort = short.reduce((t, x) => t + x.lengthM / 1000, 0);
  const kpi = `<section class="s" style="margin:0 0 32px"><div class="shead"><h2>What this run measured</h2><p>Counted from this corridor's scores. No assumption about failures or savings.</p></div>
    <div class="stats" style="grid-template-columns:repeat(4,minmax(0,1fr))">
    <div class="stat"><div class="v">${kmAll.toFixed(1)} km</div><p>assessed in ${scored.length} segments${segs.length - scored.length ? `, ${segs.length - scored.length} missing data` : ''}.</p></div>
    <div class="stat"><div class="v">${flagged.length}</div><p>segment${flagged.length === 1 ? '' : 's'} at or above the Medium threshold (${cfg.tiers.amber}) for ${STOP_LABEL[stop].toLowerCase()}.</p></div>
    <div class="stat"><div class="v">${scored.length} → ${short.length}</div><p>first review list: ${flagged.length ? 'the flagged segments' : 'the top 3 by score, since none is flagged'}, ${sumAll ? Math.round(100 * sumShort / sumAll) : 0}% of the corridor's total score in ${kmAll ? Math.round(100 * kmShort / kmAll) : 0}% of its length.</p></div>
    <div class="stat"><div class="v">${short.length * VISIT_H} h</div><p>field time for that list at ${VISIT_H} h a visit (our assumption), against ${scored.length * VISIT_H} h to walk every segment once.</p></div></div></section>`;
  let v;
  const be = `One avoided failure at ${fmt$(cfg.money.costOfFailure)} pays for ${s.yearsPaidByOneFailure} years of the program; the program breaks even at ${s.breakEvenFailures} avoided failure${s.breakEvenFailures === 1 ? '' : 's'} over ${yrs} years.`;
  if (m.risk >= 0) v = { ok: true, title: 'Protection case is positive under these assumptions',
    why: `Scenario: targeted inspections and reallocated effort outweigh the program cost by <b>${fmt$(m.risk)}</b> over ${yrs} years. This is expected-value arithmetic on the assumptions at left, not a measured saving.`, dep: be };
  else v = { ok: false, title: 'Protection case is not positive under these assumptions',
    why: `Scenario: the program costs <b>${fmt$(-m.risk)}</b> more than the expected loss it avoids over ${yrs} years. That is an acceptable answer: on a low-hazard corridor the value is the ranked shortlist above, not a dollar return.`, dep: be };
  mVerdict.innerHTML = kpi + `<div class="verdict ${v.ok ? '' : 'warn'}"><h3>${v.title}</h3><p>${v.why}</p>${v.dep ? `<p class="dep">${v.dep}</p>` : ''}
    <p class="dep">The 0–100 score is a priority index. The failure rate is our assumed base rate scaled by the score, not a validated probability. Solar lease income is not counted here.</p></div>`;

  mNet.innerHTML = `<div class="label">Pipeline-protection scenario over ${yrs} years (assumption-based, not measured)</div>
    <div class="huge" style="color:${m.risk >= 0 ? 'var(--green)' : 'var(--red)'}">${fmt$(m.risk)}</div>
    <p class="muted" style="margin:0 0 8px;max-width:60ch">Excludes solar. The conditional solar opportunity is listed separately below.</p>`;

  const rows = [
    ['grp', 'Protect the pipeline'],
    ['Expected loss avoided (scenario)', `inspections on the ${s.workOrders} flagged km · assumed base rate × score multiplier × ${Math.round(cfg.money.mitigationEffectiveness * 100)}% effectiveness`, s.lossAvoided],
    ['Inspection effort reallocated', `only if the regulator approves a risk-based cycle on low-risk km · ${fmt$(s.inspectionSavingsYr)}/yr × ${yrs}`, s.inspectionSavingsYr * yrs],
    ['Targeted inspections', `${s.workOrders} × ${fmt$(cfg.money.workOrderCost)}`, -s.workOrderCost],
    ['Running the program', `${fmt$(cfg.money.programCostYr)}/yr × ${yrs}`, -s.programCost],
  ];
  const vals = rows.filter((r) => r[0] !== 'grp').map((r) => Math.abs(r[2]));
  const max = Math.max(...vals, Math.abs(m.risk), 1);
  const bar = (x, strong) => { const w = Math.abs(x) / max * 50; return `<span class="trk"><b></b><i style="left:${x < 0 ? 50 - w : 50}%;width:${w}%;background:${x >= 0 ? C.green : strong ? C.red : C.ink3}"></i></span>`; };
  const money = (x) => `${x >= 0 ? '+' : ''}${fmt$(x)}`;
  mWf.innerHTML = rows.map((r) => r[0] === 'grp' ? `<div class="wf grp">${r[1]}</div>`
    : r[0] === 'sub' ? `<div class="wf"><span class="l" style="color:var(--ink-2)">${r[1]}</span>${bar(r[2], true)}<span class="n" style="color:var(--ink-2)">${money(r[2])}</span></div>`
    : `<div class="wf"><span class="l">${r[0]}<small>${r[1]}</small></span>${bar(r[2])}<span class="n">${money(r[2])}</span></div>`).join('') +
    `<div class="wf total"><span class="l">Pipeline protection, net (scenario)</span>${bar(m.risk, true)}<span class="n">${money(m.risk)}</span></div>`;

  const at = (cost) => moneyCase(ENGINE.mergeConfig({ ...cfg, money: { ...cfg.money, costOfFailure: cost } })).risk;
  mScen.innerHTML = [[430000, 'Low: average ground-movement failure', 'Water-main average (AWWA), not an oil and gas figure'], [2250000, 'Mid: geometric midpoint', 'Our interpolation between the two sourced figures'], [11700000, 'High: one geohazard rupture', 'A single sourced incident, not a typical cost']].map(([c, t, src]) => {
    const x = at(c); return `<button data-cost="${c}" class="${cfg.money.costOfFailure === c ? 'on' : ''}"><small>${t} · ${fmt$(c)}</small><span class="v" style="color:${x >= 0 ? 'var(--green)' : 'var(--red)'}">${fmt$(x)}</span><small>${src}. Protection only, over ${yrs} years.</small></button>`; }).join('');
  mScen.querySelectorAll('[data-cost]').forEach((b) => b.onclick = () => { sCost.value = sliderFromCost(+b.dataset.cost); recompute(); });

  mLease.innerHTML = `<div class="stats" style="grid-template-columns:repeat(4,minmax(0,1fr))">
    <div class="stat"><div class="v">${fmt$(m.operatorLease)}</div><p>hypothetical operator lease share over ${yrs} years on a ${cfg.buildStripM} m strip, if every screened stretch were leased at $${rate} an acre.</p></div>
    <div class="stat"><div class="v">${fmt$(s.partnerRevenueYr)}</div><p>a year to landowner partners at a ${Math.round(share * 100)}% share.</p></div>
    <div class="stat"><div class="v">${s.mw} MW</div><p>of solar on ${s.buildableKm} km, about ${Math.round((s.mwhYr || 0) / 1000).toLocaleString()} GWh a year.</p></div>
    <div class="stat"><div class="v">${(s.avoidedTco2Yr || 0).toLocaleString()}</div><p>tonnes of CO₂ avoided a year if built.</p></div></div>`;
}

