/* ---------- audit ---------- */
async function act(s, action, details) {
  const entry = { at: new Date().toISOString(), segment: s.id, action, details, score: s.risk[stop].score, projection: STOP_LABEL[stop], by: 'operator (demo)' };
  const item = { ...entry, note: API ? 'sending to n8n…' : 'local demo, this browser only' };
  audit.unshift(item); renderLog();
  if (API) {
    try {
      const r = await fetch(API + '/action', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(entry) });
      let body = null; try { body = await r.json(); } catch (e) {}
      if (r.ok && body && body.ok !== false) {
        item.note = 'stored in n8n';
        if (body.workOrder) s.workOrder = { ...body.workOrder, delivery: 'n8n' };
        else if (s.workOrder && action === 'approve_work_order') s.workOrder = { ...s.workOrder, id: body.work_order_id || s.workOrder.id, delivery: 'n8n' };
        // Only now, with n8n's confirmation, say it was recorded.
        if (action === 'approve_work_order') toast(`Recorded in n8n: ${body.work_order_id || s.workOrder.id} · approved${body.duplicate ? ' (already on file, no duplicate created)' : ''}. Not dispatched: export the CSV for the coordinator.`);
        else if (action === 'reject_work_order') toast(`${s.id}: rejection recorded in n8n.`);
        else toast(`${s.id}: override recorded in n8n.`);
      } else {
        item.note = 'n8n refused: ' + ((body && body.error) || r.status);
        if (s.workOrder && s.workOrder.delivery === 'sending') s.workOrder.delivery = 'failed';
        toast(`Not recorded: n8n refused (${(body && body.error) || r.status}).`);
      }
    } catch (e) { item.note = 'n8n unreachable, kept in this browser only'; if (s.workOrder && s.workOrder.delivery === 'sending') s.workOrder.delivery = 'failed'; toast('Not recorded: n8n could not be reached. Kept in this browser only.'); }
    renderLog(); renderPage();
  }
}

/* ---------- input ---------- */
function stepSel(d) {
  const i = selected ? segs.findIndex((s) => s.id === selected) : (d > 0 ? -1 : segs.length);
  const j = Math.max(0, Math.min(segs.length - 1, i + d));
  go(['triage', 'build', 'segment'].includes(page) ? page : 'triage', segs[j].id);
}
function wire() {
  addEventListener('hashchange', onRoute);
  document.addEventListener('click', (e) => { const b = e.target instanceof Element && e.target.closest('[data-stop]'); if (b) setStop(b.dataset.stop); });
  bPlay.onclick = play;
  try { if (localStorage.getItem('tc-hint') === '1') ovHint.hidden = true; } catch (e) {}
  bHint.onclick = () => { ovHint.hidden = true; try { localStorage.setItem('tc-hint', '1'); } catch (e) {} requestAnimationFrame(() => map.invalidateSize()); };
  basemap.querySelectorAll('button').forEach((b) => b.onclick = () => {
    basemap.querySelectorAll('button').forEach((x) => x.classList.toggle('on', x === b));
    for (const [k, l] of Object.entries(baseLayers)) k === b.dataset.bm ? l.addTo(map) : map.removeLayer(l);
  });
  document.querySelectorAll('input[type=range]').forEach((r) => r.oninput = recompute);
  bReset.onclick = () => { sCost.value = 0; sRate.value = 5; sEff.value = 75; sLease.value = 400; sStrip.value = 60; sShare.value = 50; sProg.value = 50000; recompute(); };
  strip.addEventListener('mousemove', (e) => { if (!G) return; const i = stripIndex(e); setHover(i < 0 ? null : segs[i].id); });
  strip.addEventListener('mouseleave', () => setHover(null));
  strip.addEventListener('click', (e) => { if (!G) return; const i = stripIndex(e); if (i >= 0) select(segs[i].id); });
  new ResizeObserver(() => drawStrip()).observe(strip);
  addEventListener('keydown', (e) => {
    if ((e.target instanceof Element && e.target.closest('input, select, textarea, summary')) || e.metaKey || e.ctrlKey || e.altKey) return;
    const k = e.key.toLowerCase();
    if (k === 'arrowright' || k === 'j') { e.preventDefault(); stepSel(1); }
    else if (k === 'arrowleft' || k === 'k') { e.preventDefault(); stepSel(-1); }
    else if (k === 'escape') { if (page === 'segment') go('triage', selected); else if (selected) go(page); }
    else if (k === 'p') play();
    else if (k === 't') setStop(STOPS[(STOPS.indexOf(stop) + 1) % STOPS.length]);
    else if (k === 'a' && selected) decide(byId(selected), 'approved');
    else if (k === 'r' && selected) decide(byId(selected), 'rejected');
    else if ('12345'.includes(k) && k) go(['overview', 'triage', 'money', 'build', 'log'][+k - 1]);
  });
